import { randomUUID } from "node:crypto";
import { NextFunction, Request, Response, Router } from "express";
import { NotFoundError } from "../application/errors";
import { TaskService } from "../application/task-service";
import { DomainError } from "../domain/errors";
import { isTaskStatus } from "../domain/task-status";

export class TaskController {
  public readonly router = Router();

  public constructor(private readonly service: TaskService) {
    this.router.post("/users", this.createUser);
    this.router.post("/projects", this.createProject);
    this.router.post("/projects/:projectId/tasks", this.createTask);
    this.router.get("/projects/:projectId/tasks", this.listTasks);
    this.router.post("/tasks/:taskId/done", this.markDone);
  }

  private createUser = (req: Request, res: Response, next: NextFunction): void => {
    try { res.status(201).json(this.service.createUser({ id: readString(req.body, "id") ?? randomUUID(), name: requiredString(req.body, "name") })); } catch (error) { next(error); }
  };
  private createProject = (req: Request, res: Response, next: NextFunction): void => {
    try { res.status(201).json(this.service.createProject({ id: readString(req.body, "id") ?? randomUUID(), name: requiredString(req.body, "name") })); } catch (error) { next(error); }
  };
  private createTask = (req: Request, res: Response, next: NextFunction): void => {
    try {
      const status = readString(req.body, "status");
      if (status !== undefined && !isTaskStatus(status)) throw new DomainError("Status must be todo, in_progress, or done");
      res.status(201).json(this.service.createTask({ id: readString(req.body, "id") ?? randomUUID(), projectId: requiredParam(req, "projectId"), title: requiredString(req.body, "title"), description: readString(req.body, "description") ?? "", dueDate: readString(req.body, "dueDate"), assigneeId: readString(req.body, "assigneeId"), status }));
    } catch (error) { next(error); }
  };
  private listTasks = (req: Request, res: Response, next: NextFunction): void => {
    try {
      const status = typeof req.query.status === "string" ? req.query.status : undefined;
      if (status !== undefined && !isTaskStatus(status)) throw new DomainError("Invalid status filter");
      res.json(this.service.listProjectTasks(requiredParam(req, "projectId"), { status, assigneeId: typeof req.query.assigneeId === "string" ? req.query.assigneeId : undefined }));
    } catch (error) { next(error); }
  };
  private markDone = (req: Request, res: Response, next: NextFunction): void => {
    try { res.json(this.service.markTaskDone(requiredParam(req, "taskId"))); } catch (error) { next(error); }
  };
}

function readString(body: unknown, key: string): string | undefined {
  return typeof body === "object" && body !== null && typeof (body as Record<string, unknown>)[key] === "string" ? (body as Record<string, string>)[key] : undefined;
}
function requiredString(body: unknown, key: string): string {
  const value = readString(body, key);
  if (value === undefined) throw new DomainError(`${key} is required`);
  return value;
}
function requiredParam(req: Request, key: string): string {
  const value = req.params[key];
  if (typeof value !== "string") throw new DomainError(`${key} is required`);
  return value;
}

export function errorHandler(error: unknown, _req: Request, res: Response, _next: NextFunction): void {
  if (error instanceof DomainError) { res.status(400).json({ error: error.message }); return; }
  if (error instanceof NotFoundError) { res.status(404).json({ error: error.message }); return; }
  res.status(500).json({ error: "Internal server error" });
}

